// Volatility Sentinel Analysis
const ticker = $('Get BTC Ticker').first().json;
const ohlc = $('Get Hourly OHLC').first().json;

const btc = ticker.tickers?.XXBTZUSD;
if (!btc) {
  return [{ json: { action: 'skip', reason: 'No ticker data' } }];
}

const currentPrice = btc.price;
const high24h = btc.high_24h;
const low24h = btc.low_24h;

// 24h volatility (range as % of price)
const range24h = high24h - low24h;
const volatility24h = (range24h / currentPrice) * 100;

// Calculate recent volatility from hourly candles (last 6 hours)
const candles = ohlc.ohlc || [];
const recentCandles = candles.slice(-6);
let recentHighs = [], recentLows = [];
for (const c of recentCandles) {
  recentHighs.push(parseFloat(c[2])); // high
  recentLows.push(parseFloat(c[3]));  // low
}
const recentHigh = Math.max(...recentHighs);
const recentLow = Math.min(...recentLows);
const recentRange = recentHigh - recentLow;
const recentVolatility = (recentRange / currentPrice) * 100;

// Volatility regimes
const HIGH_VOL_THRESHOLD = 6;   // >6% = high volatility
const LOW_VOL_THRESHOLD = 2;    // <2% = low volatility

let regime = 'normal';
let alertLevel = 'info';
let recommendation = '';

if (volatility24h > HIGH_VOL_THRESHOLD) {
  regime = 'high';
  alertLevel = 'warning';
  recommendation = 'High volatility detected. Consider pausing new entries or increasing dip thresholds. Big moves beget big moves.';
} else if (volatility24h < LOW_VOL_THRESHOLD) {
  regime = 'low';
  alertLevel = 'info';
  recommendation = 'Low volatility. Safer for market making but fewer opportunities. Normal DCA is fine.';
} else {
  regime = 'normal';
  alertLevel = 'info';
  recommendation = 'Normal volatility. Continue standard strategy.';
}

// Trend detection (is price near high or low of range?)
const positionInRange = (currentPrice - low24h) / range24h;
let trend = 'neutral';
if (positionInRange > 0.8) trend = 'near_high';
else if (positionInRange < 0.2) trend = 'near_low';

return [{
  json: {
    timestamp: new Date().toISOString(),
    current_price: currentPrice,

    volatility: {
      range_24h: range24h,
      volatility_24h_pct: volatility24h,
      recent_6h_volatility_pct: recentVolatility,
      high_24h: high24h,
      low_24h: low24h
    },

    regime: regime,
    alert_level: alertLevel,
    recommendation: recommendation,

    trend: {
      position_in_range: positionInRange,
      direction: trend
    },

    thresholds: {
      high_vol: HIGH_VOL_THRESHOLD,
      low_vol: LOW_VOL_THRESHOLD
    }
  }
}];

const v = $input.first().json;
console.log('=== VOLATILITY ALERT ===');
console.log('24h Volatility: ' + v.volatility.volatility_24h_pct.toFixed(2) + '%');
console.log('Range: $' + v.volatility.low_24h.toFixed(0) + ' - $' + v.volatility.high_24h.toFixed(0));
console.log('Regime: ' + v.regime.toUpperCase());
console.log('Trend: ' + v.trend.direction);
console.log('Recommendation: ' + v.recommendation);
return [{ json: { alert: true, ...v } }];

